package com.oai.harmonywake; import android.app.*; import android.content.*; import android.os.*; import android.view.*; import android.widget.*; public class WakeActivity extends Activity { protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON|WindowManager.LayoutParams.FLAG_DISMISS_KEYGUARD);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);} TextView v=new TextView(this);v.setText("Harmony Wake 正在唤醒目标应用…");v.setTextSize(22);v.setPadding(48,80,48,48);setContentView(v);WakeTask t=TaskStore.find(this,getIntent().getIntExtra("task_id",-1));if(t!=null&&!t.packageName.isEmpty())try{Intent x=getPackageManager().getLaunchIntentForPackage(t.packageName);if(x!=null){x.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);startActivity(x);}}catch(Exception e){}v.postDelayed(this::finish,1500);}}